// ---- device properties ----------------------------------------------------
#define hipGetDeviceProperties cudaGetDeviceProperties
// cudaDeviceProp has no gcnArchName; map it to name so AMD device-detection
// code (e.g. strstr(p.gcnArchName, "gfx942")) keeps compiling and simply
