// meta/benchmarks/test_gemm_bf16_correct.cu
//
// End-to-end correctness test for the CUDA wmma bf16 GEMM (issue #29 port)
// on NVIDIA, against the CPU reference in vkernels::kernels::gemm_bf16_cpu.
//
// It checks two things:
//   1. The public entry cuda::gemm_bf16 (config-selected tile) matches the
//      CPU oracle within bf16 tolerance for every Kimi-K3 projection
//      (N, K) shape at serving M = {8, 64} and warmup M = 8192.
//   2. Every compiled tile (16x16, 16x64, 16x128, 32x64, 32x128, 64x64,
//      64x128) -- exercised only through the explicit-tile
//      cuda::gemm_bf16_with_config dispatcher -- also matches the oracle on
//      a small, awkward (M=16, N=100, K=128) shape.
//
// Tolerance: A and C are bf16, B is bf16, accumulation is fp32. The device
// wmma sums K in 16-element hardware blocks while the CPU oracle sums K
// sequentially; after the single round-to-nearest-even on store the two
// agree to within ~1 bf16 ULP. We report max_abs / max_rel and require
// max_rel < 2e-2 (same convention as test_gemm_bf16_correct.hip).

#include <cuda_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/gemm_bf16.hpp"

// The explicit-tile dispatcher is intentionally not in the public header
// (vkl discovery), so the harness forward-declares it here.
namespace vkernels::kernels::cuda {
void gemm_bf16_with_config(std::size_t M, std::size_t N, std::size_t K,
                           float alpha, const uint16_t* A,
                           const uint16_t* B, float beta, uint16_t* C,
                           int bm, int bn, int bk, int threads);
}  // namespace vkernels::kernels::cuda

#define CK(e, m)                                                       \
  do {                                                                 \
    cudaError_t r = (e);                                               \
    if (r != cudaSuccess) {                                            \
      std::fprintf(stderr, "%s: %s\n", m, cudaGetErrorString(r));      \
      std::exit(1);                                                    \
    }                                                                  \
  } while (0)

namespace {

float rnd(int seed, int i) {  // deterministic pseudo-random in [-1, 1]
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;
}

uint16_t f2bf(float v) {
  uint32_t b; std::memcpy(&b, &v, 4);
  b += 0x7FFFu + ((b >> 16) & 1);
  return (uint16_t)(b >> 16);
}

// One shape: CPU oracle vs CUDA, alpha/beta configurable.
struct Stats { double max_abs, max_rel; };

Stats run_case(int M, int N, int K, float alpha, float beta,
               const std::vector<uint16_t>& A,
               const std::vector<uint16_t>& B,
               const std::vector<uint16_t>& Cinit,
               uint16_t* dA, uint16_t* dB, uint16_t* dC) {
  std::vector<uint16_t> hC(Cinit), rC(Cinit);
  // CPU reference.
  vkernels::kernels::gemm_bf16_cpu(
      (size_t)M, (size_t)N, (size_t)K, alpha, A.data(), B.data(), beta,
      rC.data());
  // Device.
  CK(cudaMemcpy(dA, A.data(), (size_t)M * K * 2, cudaMemcpyHostToDevice),
     "cpyA");
  CK(cudaMemcpy(dB, B.data(), (size_t)K * N * 2, cudaMemcpyHostToDevice),
     "cpyB");
  CK(cudaMemcpy(dC, Cinit.data(), (size_t)M * N * 2, cudaMemcpyHostToDevice),
     "cpyC");
  vkernels::kernels::cuda::gemm_bf16(
      (size_t)M, (size_t)N, (size_t)K, alpha, dA, dB, beta, dC);
  CK(cudaDeviceSynchronize(), "sync");
  CK(cudaMemcpy(hC.data(), dC, (size_t)M * N * 2, cudaMemcpyDeviceToHost),
     "rdC");

  Stats s{0.0, 0.0};
  for (int i = 0; i < M * N; ++i) {
    float hf, rf;
    uint32_t hu = (uint32_t)hC[i] << 16, ru = (uint32_t)rC[i] << 16;
    std::memcpy(&hf, &hu, 4); std::memcpy(&rf, &ru, 4);
    double e = std::fabs((double)hf - rf);
    if (e > s.max_abs) s.max_abs = e;
    double d = std::fmax(std::fabs((double)rf), 1.0);
    if (e / d > s.max_rel) s.max_rel = e / d;
  }
  return s;
}

void fill_AB(std::vector<uint16_t>& A, std::vector<uint16_t>& B,
             int M, int N, int K, int seed) {
  for (int i = 0; i < M * K; ++i) A[i] = f2bf(rnd(seed, i) * 0.5f);
  for (int i = 0; i < K * N; ++i) B[i] = f2bf(rnd(seed + 7, i) * 0.5f);
}

}  // namespace

int main() {
  cudaDeviceProp p;
  CK(cudaGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (sm_%d%d)\n", p.name, p.major, p.minor);

  // Largest buffers we will need (M=8192, N=6288, K=7168) plus headroom.
  const int MAXM = 8192, MAXN = 6288, MAXK = 7168;
  uint16_t *dA, *dB, *dC;
  CK(cudaMalloc(&dA, (size_t)MAXM * MAXK * 2), "alloc A");
  CK(cudaMalloc(&dB, (size_t)MAXK * MAXN * 2), "alloc B");
  CK(cudaMalloc(&dC, (size_t)MAXM * MAXN * 2), "alloc C");

  // Kimi-K3 projection (N, K) shapes from the issue.
  struct NK { int N, K; };
  const NK k3[] = {
      {6288, 7168}, {3584, 7168}, {896, 7168}, {2112, 7168}, {1536, 7168},
      {7168, 1536}, {7168, 768}, {7168, 3584}, {2304, 1536}, {3072, 512},
      {1536, 128},
  };

  int fails = 0;
  const float THRESH = 2e-2;

  // --- (1) public entry, serving M ---
  for (int M : {8, 64}) {
    std::printf("\n--- serving M=%d (public cuda::gemm_bf16) ---\n", M);
    for (const auto& s : k3) {
      std::vector<uint16_t> A((size_t)M * s.K), B((size_t)s.K * s.N),
          C((size_t)M * s.N, 0);
      fill_AB(A, B, M, s.N, s.K, 1);
      // beta != 0 on a few cases; else 0 (no C read).
      float beta = ((M + s.N) % 5 == 0) ? 0.5f : 0.0f;
      for (size_t i = 0; i < C.size(); ++i) C[i] = f2bf(rnd(3, (int)i) * 0.3f);
      auto st = run_case(M, s.N, s.K, 1.0f, beta, A, B, C, dA, dB, dC);
      bool ok = st.max_rel < THRESH;
      std::printf("  M=%-4d N=%-4d K=%-4d beta=%.1f  max_abs=%.4f "
                  "max_rel=%.6f  %s\n",
                  M, s.N, s.K, beta, st.max_abs, st.max_rel,
                  ok ? "PASS" : "FAIL");
      if (!ok) ++fails;
    }
  }

  // --- (1b) public entry, warmup M=8192 (small (N,K) only; CPU is O(MNK)) ---
  {
    const int M = 8192;
    std::printf("\n--- warmup M=%d (public cuda::gemm_bf16) ---\n", M);
    const NK warm[] = {{1536, 128}, {3072, 512}};
    for (const auto& s : warm) {
      std::vector<uint16_t> A((size_t)M * s.K), B((size_t)s.K * s.N),
          C((size_t)M * s.N, 0);
      fill_AB(A, B, M, s.N, s.K, 2);
      auto st = run_case(M, s.N, s.K, 1.0f, 0.0f, A, B, C, dA, dB, dC);
      bool ok = st.max_rel < THRESH;
      std::printf("  M=%-4d N=%-4d K=%-4d  max_abs=%.4f max_rel=%.6f  %s\n",
                  M, s.N, s.K, st.max_abs, st.max_rel, ok ? "PASS" : "FAIL");
      if (!ok) ++fails;
    }
  }

  // --- (2) every compiled tile via cuda::gemm_bf16_with_config ---
  // Awkward shape: M=16 (one 16-row tile, or part of a 32/64 tile),
  // N=100 (not a multiple of 16/64), K=128 (two K-tiles).
  {
    const int M = 16, N = 100, K = 128;
    std::vector<uint16_t> A((size_t)M * K), B((size_t)K * N), C((size_t)M * N, 0);
    fill_AB(A, B, M, N, K, 5);
    std::vector<uint16_t> rC(C);
    vkernels::kernels::gemm_bf16_cpu((size_t)M, (size_t)N, (size_t)K, 1.0f,
                                     A.data(), B.data(), 0.0f, rC.data());
    struct Cfg { int bm, bn; };
    const Cfg cfgs[] = {{16, 16}, {16, 64},  {16, 128}, {32, 64},
                        {32, 128}, {64, 64},  {64, 128}};
    std::printf("\n--- explicit-tile sweep (M=%d N=%d K=%d, "
                "cuda::gemm_bf16_with_config) ---\n",
                M, N, K);
    for (const auto& c : cfgs) {
      std::vector<uint16_t> hC(C);
      CK(cudaMemcpy(dA, A.data(), (size_t)M * K * 2, cudaMemcpyHostToDevice),
         "cpyA");
      CK(cudaMemcpy(dB, B.data(), (size_t)K * N * 2, cudaMemcpyHostToDevice),
         "cpyB");
      CK(cudaMemcpy(dC, C.data(), (size_t)M * N * 2, cudaMemcpyHostToDevice),
         "cpyC");
      vkernels::kernels::cuda::gemm_bf16_with_config(
          (size_t)M, (size_t)N, (size_t)K, 1.0f, dA, dB, 0.0f, dC, c.bm, c.bn,
          64, (c.bm / 16) * (c.bn / 16) * 32);
      CK(cudaDeviceSynchronize(), "sync");
      CK(cudaMemcpy(hC.data(), dC, (size_t)M * N * 2, cudaMemcpyDeviceToHost),
         "rdC");
      double ma = 0, mr = 0;
      for (int i = 0; i < M * N; ++i) {
        float hf, rf;
        uint32_t hu = (uint32_t)hC[i] << 16, ru = (uint32_t)rC[i] << 16;
        std::memcpy(&hf, &hu, 4); std::memcpy(&rf, &ru, 4);
        double e = std::fabs((double)hf - rf);
        if (e > ma) ma = e;
        double d = std::fmax(std::fabs((double)rf), 1.0);
        if (e / d > mr) mr = e / d;
      }
      bool ok = mr < THRESH;
      std::printf("  tile %2dx%-3d  max_abs=%.4f max_rel=%.6f  %s\n", c.bm,
                  c.bn, ma, mr, ok ? "PASS" : "FAIL");
      if (!ok) ++fails;
    }
  }

  cudaFree(dA); cudaFree(dB); cudaFree(dC);
  std::printf("\n%s (%d failure(s))\n", fails ? "FAIL" : "PASS", fails);
  return fails ? 1 : 0;
}

// meta/benchmarks/test_dsa_topk_correct.cu
//
// End-to-end correctness test for the CUDA wmma DSA paged-MQA gated top-k
// logits (issue #51 CUDA port) on NVIDIA, against the CPU reference in
// vkernels::kernels::dsa_topk_logits_cpu.
//
//   cuda::dsa_topk_logits  vs  dsa_topk_logits_cpu (the gated-logit oracle)
//
// GLM-5.3-Flash indexer (index_n_heads=32, index_head_dim=128, block=64) at
// batch in {1, 2} and max_table_len in {8, 16} (max_seq_len in {512, 1024}),
// plus smaller sanity shapes and the 2x/4x indexer (H=64/128). seq_lens are
// truncated on a couple of cases to exercise the t < seq_len write guard,
// and split_kv=2 on one case to verify the grid's perf-only slicing is
// actually grouping-independent. Every kernel variant (fp32-Q, fp8-Q, wmma)
// is FORCED at the GLM-5.3 shape (H=32 fits all three) so every path stays
// exercised even when the auto dispatcher would pick a different one.
//
// Method. The source Q and K are torch.float8_e4m3fnuz (raw uint8). The
// harness generates fp8 bytes directly, then BOTH paths dequant them via the
// SAME helper (fp8e4m3fnuz_to_f32 -- copied verbatim into the anonymous
// namespace below): the CPU oracle runs on the host-dequanted fp32, the
// device kernel dequants on load. With identical dequant, the only residual
// is FMA vs IEEE mul+add over the D-dot and H-sum (a few ULP), so we require
// max_rel < 1e-3 (same convention as test_dsa_topk_correct.hip).
//
// Invariant (the caller contract the kernel relies on): page_table[b,i] is
// VALID (in [0, num_blocks)) for every used slot i < ceildiv(seq_len, B).
// Unused slots (i >= ceildiv(seq_len, B)) are never read. The harness only
// generates valid pages in used slots; the CPU oracle ADDITIONALLY masks OOB
// pages (defensive), but the kernel has no such guard -- it relies on
// sglang's invariant, so the harness must respect it.
//
// Built only with VKERNELS_HAS_CUDA (and NOT VKERNELS_HAS_HIP -- on a
// dual-GPU box the .hip bench already provides test_dsa_topk_correct).

#include <cuda_runtime.h>

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

#include "vkernels/kernels/dsa.hpp"

#define CK(e, m)                                                       \
  do {                                                                 \
    cudaError_t r = (e);                                               \
    if (r != cudaSuccess) {                                            \
      std::fprintf(stderr, "%s: %s\n", m, cudaGetErrorString(r));      \
      std::exit(1);                                                    \
    }                                                                  \
  } while (0)

namespace {

float rnd(int seed, int i) {  // deterministic pseudo-random in [-1, 1]
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  return (float)((int)x % 200000) / 100000.0f;
}

// fp8 e4m3fnuz byte in [0,254] excluding 0x7F (+NaN) and 0xFF (-NaN) --
// mirrors real KV cache data (no NaNs; 0x00 and 0x80 both decode to +0).
uint8_t rnd_fp8(int seed, int i) {
  unsigned x = (unsigned)(seed * 2654435761u + (unsigned)i * 40503u);
  x ^= x >> 13;
  x *= 0x5bd1e995u;
  x ^= x >> 15;
  uint8_t b = (uint8_t)(x % 255u);   // 0..254 (excludes 0xFF)
  if (b == 0x7Fu) b = 0u;            // exclude +NaN; 0x00 is +0 (fine)
  return b;
}

// fp8 e4m3fnuz -> fp32. VERBATIM copy of fp8e4m3fnuz_to_f32 in
// moe_device.hip (__host__ __device__); the harness dequants on the host,
// the device kernel dequants on load via its own copy. Both MUST agree --
// the kernel's docstring asserts this, and we cross-check it here.
__host__ __device__ __forceinline__ float fp8e4m3fnuz_to_f32(uint8_t b) {
  const uint32_t s = static_cast<uint32_t>(b >> 7) & 1u;     // sign
  const uint32_t e = static_cast<uint32_t>(b >> 3) & 0xFu;   // exponent (bias 8)
  const uint32_t m = static_cast<uint32_t>(b) & 0x7u;        // mantissa (3)
  if ((b & 0x7Fu) == 0u) return 0.0f;                        // +0 (0x00 AND 0x80)
  float f;
  if (e == 15u && m == 7u) {                                 // 0x7F = NaN -> qNaN
    const uint32_t qnan = 0x7fc00000u;
    __builtin_memcpy(&f, &qnan, sizeof(f));
  } else if (e == 0u) {                                      // subnormal: m*2^-7
    const float v = static_cast<float>(m) * 0x1p-7f;         // m*2^(1-8), exact
    f = s ? -v : v;
  } else {                                                   // normal: 2^(e-8)*(1+m/8)
    const uint32_t bits = (s << 31) | ((e + 119u) << 23) | (m << 20);
    __builtin_memcpy(&f, &bits, sizeof(f));
  }
  return f;
}

struct Stats { double max_abs, max_rel; };

void cmp_out(const std::vector<float>& got, const std::vector<float>& ref,
             Stats* s) {
  for (size_t i = 0; i < ref.size(); ++i) {
    double e = std::fabs((double)got[i] - ref[i]);
    if (e > s->max_abs) s->max_abs = e;
    double d = std::fmax(std::fabs((double)ref[i]), 1.0);
    if (e / d > s->max_rel) s->max_rel = e / d;
  }
}

}  // namespace

int main() {
  cudaDeviceProp p;
  CK(cudaGetDeviceProperties(&p, 0), "props");
  std::printf("GPU: %s (sm_%d%d)\n", p.name, p.major, p.minor);

