// Dispatch shim shared by dsa_topk_logits (auto) and
// dsa_topk_logits_with_variant (explicit). `variant`: 0 = auto
// (wmma -> fp32q -> fp8q -> refuse); 1 = fp32-Q; 2 = fp8-Q; 3 = wmma.
