// but against the GB10 opt-in cap). Pure arithmetic.
static bool fits_lds_fp8q(int H, int D, int B) {
  const int bytes = (H + B * D + B) * 4 + H * D;
  return bytes > 0 && bytes <= kGb10LdsOptin;
}

